setup_replacements.old:
// Validate timestamp is within acceptable range:
// - Not too far in the past (before hook started minus skew)
// - Not too far in the future (after hook started plus skew)
lowerBound := hookStartTime.Add(-maxSkew)
upperBound := hookStartTime.Add(maxSkew)
if ts.After(lowerBound) && ts.Before(upperBound) {
	return true
}

setup_replacements.new:
// Validate the entry was not written in the future relative to this
// hook invocation (allowing for clock skew). Writes can lag the hook
// start by more than the skew window on loaded machines, so rejecting
// older entries here would make the wait flaky.
upperBound := hookStartTime.Add(maxSkew)
if ts.Before(upperBound) {
	return true
}
